WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pf_tp_acc'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '分段累计收费', 'kp-pf-tp-acc', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "分段累计收费（水电气费、个税）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心原则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "阶梯计价，一段一段算，不能拿总数直接乘最高阶梯的单价！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[明确各个区间的门槛和单价] --> B[判断总数量落在了哪个区间]\nB --> C[第一段: 门槛1 × 单价1]\nC --> D[第二段: (门槛2 - 门槛1) × 单价2]\nD --> E[最后一段: (总数 - 上一个门槛) × 当前单价]\nE --> F[把所有段的钱加起来]"}}]}$$ AS jsonb), NULL, '分段累计收费的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "分段累计收费"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_tp_acc", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
